                Blocks(Paragraph(Text("For every arbitrary measurable probability seed space, permitted bias, endpoint j and k at least one, W is lawful, has total cap k on every source and seed, and every formal branch returns with a paid count between one and k. For every measurable seed set B and every observation z its full-law rectangle mass is nu(B) times stoppingMass(beta,k,z). Every actual read of W has distance at most 2k+1 from j."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-rule-radius-lower"), DeclarationHandle.Create(Prefix + "original_rule_radius_lower"),
