                Blocks(Paragraph(Text("For every arbitrary probability seed space U, bias beta, endpoint j, ambient-lawful CompletedRule Q, natural k with Q.TotalCap(k), and measurable source observation w whose seed joint law equals Q.fullLaw, there is a measurable selector T:U to trees of height at most k. Q.normalize equals T(seed) product-almost everywhere; for almost every seed the equality holds source-almost everywhere and every observation mass equals the source mass of w. No everywhere selector identity is asserted for ambient null changes."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-rule-stopping-results"), DeclarationHandle.Create(Prefix + "original_rule_stopping_results"),
