                Blocks(Paragraph(Text("For every arbitrary measurable probability seed space, permitted bias, endpoint j, k at least one, ambient-lawful completed Q with total cap k and the full law of W, there is one measurable bounded tree selector. Almost every seed has source-almost-everywhere agreement with the actual completed expansion and the exact detached k-node stopping-path geometry. The actual completed remote probability is at least (1+T(k))/2; W attains equality, and when k=1 the competitor probability is one."))), DescribeRole.Theorem),
            Paragraph(Text("For both raw and ambient completed competitors, the natural radii admitting a lawful total-cap-k representative with this same full law have least element 2k+1. The witness realizes membership on the same U and nu, and the actual remote event excludes each smaller radius. This is the minimum for the witness law at fixed k; it does not assert universal all-k radius nonemptiness for arbitrary inputs.")))));
    private static Formula N(string name) => F.Seq(Operatorname, Grp(F.Id(name)));
    private static Formula A(string name, params Formula[] args)
    {
        var parts = new System.Collections.Generic.List<Formula> { N(name), Sp, Open };
        for (var i = 0; i < args.Length; i++)
        {
            if (i > 0) parts.Add(F.Seq(Comma, Sp));
            parts.Add(args[i]);
        }
        parts.Add(Close);
        return F.Seq(parts.ToArray());
    }
    private static Formula All(string name, Formula type, Formula body) =>
        F.Seq(Forall, Sp, Open, N(name), Sp, Colon, Sp, type, Close, Comma, Sp, Open, body, Close);
    private static Formula Some(string name, Formula type, Formula body) =>
        F.Seq(Exists, Sp, Open, N(name), Sp, Colon, Sp, type, Close, Comma, Sp, Open, body, Close);
    private static Formula Ae(string name, Formula measure, Formula body) =>
        A("AE", measure, F.Seq(N("fun"), Sp, N(name), Sp, Mapsto, Sp, Open, body, Close));
    private static Formula Equal(Formula x, Formula y) => F.Seq(x, Sp, Eq, Sp, y);
    private static Formula Leq(Formula x, Formula y) => F.Seq(x, Sp, Le, Sp, y);
    private static Formula Imp(Formula x, Formula y) => F.Seq(Open, x, Close, Sp, To, Sp, Open, y, Close);
    private static Formula Arrow(Formula x, Formula y) => F.Seq(Open, x, Sp, To, Sp, y, Close);
    private static Formula PlusOf(Formula x, Formula y) => F.Seq(Open, x, Sp, Plus, Sp, y, Close);
    private static Formula TimesOf(Formula x, Formula y) => F.Seq(Open, x, Sp, Star, Sp, y, Close);
    private static Formula Divide(Formula x, Formula y) => F.Seq(Frac, Grp(x), Grp(y));
    private static Formula Conj(params Formula[] xs)
    {
        var parts = new System.Collections.Generic.List<Formula>();
        for (var i = 0; i < xs.Length; i++)
        {
            if (i > 0) parts.Add(F.Seq(Sp, Land, Sp));
            parts.Add(F.Seq(Open, xs[i], Close));
        }
        return F.Seq(parts.ToArray());
    }
    private static Formula WithMeasurable(Formula type, Formula body) =>
        F.Seq(OpenBracket, A("MeasurableSpace", type), CloseBracket, Sp, body);
    private static Formula WithProbability(Formula measure, Formula body) =>
        F.Seq(OpenBracket, A("IsProbabilityMeasure", measure), CloseBracket, Sp, body);

